/**
 * @file src/bus/pub.ts
 * Phase 3.2 — Publish bridge.
 *
 * gameFacade.ts cannot be imported by commandHandlers.ts due to a circular
 * dependency (gameFacade → commandHandlers → gameFacade).
 *
 * This module acts as a one-directional bridge:
 *   - gameFacade.ts registers its publish & getSnapshot functions here at init time.
 *   - commandHandlers.ts and other mutation points call publish() / getSnapshot() here.
 */

import type { GameEvent, GameEventType } from './events.js';
import type { CombatSnapshot, GameSnapshot } from './snapshots.js';

let _publish: ((event: GameEvent) => void) | null = null;
let _publishDeferred: ((eventType: GameEventType, buildEvent: () => GameEvent | null) => void) | null = null;
let _getSnapshot: (() => GameSnapshot | null) | null = null;
let _buildCombatSnapshot: (() => CombatSnapshot | null) | null = null;
let _invalidateSnapshot: (() => void) | null = null;

export function setFacadePublish(fn: (event: GameEvent) => void): void {
  _publish = fn;
}

export function setFacadePublishDeferred(
  fn: (eventType: GameEventType, buildEvent: () => GameEvent | null) => void,
): void {
  _publishDeferred = fn;
}

export function setFacadeBuildCombatSnapshot(fn: () => CombatSnapshot | null): void {
  _buildCombatSnapshot = fn;
}

export function setFacadeGetSnapshot(fn: () => GameSnapshot | null): void {
  _getSnapshot = fn;
}

export function setFacadeInvalidateSnapshot(fn: () => void): void {
  _invalidateSnapshot = fn;
}

export function invalidateSnapshotCache(): void {
  if (_invalidateSnapshot) _invalidateSnapshot();
}

export function publish(event: GameEvent): void {
  if (_publish) _publish(event);
}

/** Debounced publish; payload built when the timer fires (trailing edge). */
export function publishDeferred(
  eventType: GameEventType,
  buildEvent: () => GameEvent | null,
): void {
  if (_publishDeferred) _publishDeferred(eventType, buildEvent);
}

export function buildCombatSnapshotOnly(): CombatSnapshot | null {
  return _buildCombatSnapshot ? _buildCombatSnapshot() : null;
}

export function getSnapshot(): GameSnapshot | null {
  return _getSnapshot ? _getSnapshot() : null;
}

/** Snapshot built after cache invalidation (for publish hooks). */
export function getFreshSnapshot(): GameSnapshot | null {
  invalidateSnapshotCache();
  return getSnapshot();
}
