/**
 * @file src/bus/events.ts
 * Type definitions for all game events published through the EventBus.
 * Phase 1.5 — The facade publishes these events, UI subscribes to them.
 */

import type {
  ResourceSnapshot,
  TeamSnapshot,
  TeamHeaderStatsSnapshot,
  CombatSnapshot,
  GameSnapshot,
  StorageCardSnapshot,
  QuestsSnapshot,
  AchievementsSnapshot,
  ShopSnapshot,
  BagSnapshot,
  RocketSnapshot,
  RocketRealtimeSnapshot,
  RocketCasinoModalSnapshot,
  RocketContractModalSnapshot,
} from './snapshots';
import type { StorageSortEntry } from '../lib/storageSortUtils.js';

// ─── Event type constants (string enums for subscribe()) ───

export const GameEventType = {
  STATE_UPDATED: 'STATE_UPDATED',
  RESOURCES_CHANGED: 'RESOURCES_CHANGED',
  TEAM_CHANGED: 'TEAM_CHANGED',
  TEAM_HEADER_STATS: 'TEAM_HEADER_STATS',
  STATS_CHANGED: 'STATS_CHANGED',
  STORAGE_CHANGED: 'STORAGE_CHANGED',
  STORAGE_SORT_CHANGED: 'STORAGE_SORT_CHANGED',
  PENSION_CHANGED: 'PENSION_CHANGED',
  ZONE_CHANGED: 'ZONE_CHANGED',
  REGION_CHANGED: 'REGION_CHANGED',
  COMBAT_STARTED: 'COMBAT_STARTED',
  COMBAT_ENDED: 'COMBAT_ENDED',
  COMBAT_STATE_CHANGED: 'COMBAT_STATE_CHANGED',
  CAPTURE_STARTED: 'CAPTURE_STARTED',
  CAPTURE_ENDED: 'CAPTURE_ENDED',
  TOAST: 'TOAST',
  MODAL_OPENED: 'MODAL_OPENED',
  MODAL_CLOSED: 'MODAL_CLOSED',
  LANGUAGE_CHANGED: 'LANGUAGE_CHANGED',
  SETTINGS_CHANGED: 'SETTINGS_CHANGED',
  EGG_HATCHED: 'EGG_HATCHED',
  EVOLUTION_READY: 'EVOLUTION_READY',
  QUEST_ACCEPTED: 'QUEST_ACCEPTED',
  QUEST_COMPLETED: 'QUEST_COMPLETED',
  QUESTS_CHANGED: 'QUESTS_CHANGED',
  ACHIEVEMENTS_CHANGED: 'ACHIEVEMENTS_CHANGED',
  SHOP_CHANGED: 'SHOP_CHANGED',
  BAG_CHANGED: 'BAG_CHANGED',
  ROCKET_CHANGED: 'ROCKET_CHANGED',
  ROCKET_TICK: 'ROCKET_TICK',
  ROCKET_CASINO_CHANGED: 'ROCKET_CASINO_CHANGED',
  ROCKET_CONTRACT_CHANGED: 'ROCKET_CONTRACT_CHANGED',
  TOWER_CHANGED: 'TOWER_CHANGED',
  EXPEDITION_CHANGED: 'EXPEDITION_CHANGED',
  ARENA_CHANGED: 'ARENA_CHANGED',
  POKEDEX_CHANGED: 'POKEDEX_CHANGED',
  SHINY_FOUND: 'SHINY_FOUND',
  LEGENDARY_FOUND: 'LEGENDARY_FOUND',
  TOWER_STARTED: 'TOWER_STARTED',
  TOWER_COMPLETED: 'TOWER_COMPLETED',
  ARENA_STARTED: 'ARENA_STARTED',
  ARENA_COMPLETED: 'ARENA_COMPLETED',
  SAFE_LOADED: 'SAFE_LOADED', // TODO(3.1): rename to SAVE_LOADED after migrating all publishers
  DPS_METER_UPDATED: 'DPS_METER_UPDATED',
  FARMING_METRICS_UPDATED: 'FARMING_METRICS_UPDATED',
  MART_AUTO_PURCHASE_UPDATED: 'MART_AUTO_PURCHASE_UPDATED',
  AFK_SUMMARY_CHANGED: 'AFK_SUMMARY_CHANGED',
  MILTANK_FARM_CHANGED: 'MILTANK_FARM_CHANGED',
  FETICHE_CHANGED: 'FETICHE_CHANGED',
  ACADEMY_COURSES_CHANGED: 'ACADEMY_COURSES_CHANGED',
  Z_RING_CHANGED: 'Z_RING_CHANGED',
  POKE_PELAGO_CHANGED: 'POKE_PELAGO_CHANGED',
} as const;

export type GameEventType = (typeof GameEventType)[keyof typeof GameEventType];

// ─── Event payloads ───

export interface StateUpdatedEvent {
  type: typeof GameEventType.STATE_UPDATED;
  snapshot: GameSnapshot;
}

export interface ResourcesChangedEvent {
  type: typeof GameEventType.RESOURCES_CHANGED;
  resources: ResourceSnapshot;
}

export interface TeamChangedEvent {
  type: typeof GameEventType.TEAM_CHANGED;
  team: TeamSnapshot;
}

export interface TeamHeaderStatsChangedEvent {
  type: typeof GameEventType.TEAM_HEADER_STATS;
  header: TeamHeaderStatsSnapshot;
}

export interface StatsChangedEvent {
  type: typeof GameEventType.STATS_CHANGED;
  tab: string;
  html: string;
}

export interface StorageChangedEvent {
  type: typeof GameEventType.STORAGE_CHANGED;
  storageRoster: StorageCardSnapshot[];
  storageFilteredCountLabel: string;
  storageShowEmptyFiltered: boolean;
}

export interface StorageSortChangedEvent {
  type: typeof GameEventType.STORAGE_SORT_CHANGED;
  storageSortStack: StorageSortEntry[];
  storageSortByBaseStats: boolean;
}

export interface PensionChangedEvent {
  type: typeof GameEventType.PENSION_CHANGED;
}

export interface ZoneChangedEvent {
  type: typeof GameEventType.ZONE_CHANGED;
  zone: number;
  region: string;
  maxReachedZone: number;
  zoneName: string;
}

export interface RegionChangedEvent {
  type: typeof GameEventType.REGION_CHANGED;
  region: string;
}

export interface CombatStartedEvent {
  type: typeof GameEventType.COMBAT_STARTED;
  snapshot: CombatSnapshot;
}

export interface CombatEndedEvent {
  type: typeof GameEventType.COMBAT_ENDED;
  won: boolean;
}

export interface CombatStateChangedEvent {
  type: typeof GameEventType.COMBAT_STATE_CHANGED;
  state: string;
  combat: CombatSnapshot;
}

export interface CaptureStartedEvent {
  type: typeof GameEventType.CAPTURE_STARTED;
}

export interface CaptureEndedEvent {
  type: typeof GameEventType.CAPTURE_ENDED;
  success: boolean;
}

export interface ToastEvent {
  type: typeof GameEventType.TOAST;
  level: 'success' | 'info' | 'warning' | 'error';
  title: string;
  message: string;
}

export interface ModalOpenedEvent {
  type: typeof GameEventType.MODAL_OPENED;
  modalId: string;
}

export interface ModalClosedEvent {
  type: typeof GameEventType.MODAL_CLOSED;
  modalId: string;
}

export interface LanguageChangedEvent {
  type: typeof GameEventType.LANGUAGE_CHANGED;
  lang: string;
}

export interface SettingsChangedEvent {
  type: typeof GameEventType.SETTINGS_CHANGED;
}

export interface EggHatchedEvent {
  type: typeof GameEventType.EGG_HATCHED;
  creatureName: string;
}

export interface EvolutionReadyEvent {
  type: typeof GameEventType.EVOLUTION_READY;
}

export interface SaveLoadedEvent {
  type: typeof GameEventType.SAFE_LOADED; // TODO(3.1): SAVE_LOADED
}

export interface QuestAcceptedEvent {
  type: typeof GameEventType.QUEST_ACCEPTED;
  questId: string;
}

export interface QuestCompletedEvent {
  type: typeof GameEventType.QUEST_COMPLETED;
  questId: string;
}

export interface QuestsChangedEvent {
  type: typeof GameEventType.QUESTS_CHANGED;
  quests: QuestsSnapshot;
}

export interface AchievementsChangedEvent {
  type: typeof GameEventType.ACHIEVEMENTS_CHANGED;
  achievements: AchievementsSnapshot;
}

export interface ShopChangedEvent {
  type: typeof GameEventType.SHOP_CHANGED;
  shop: ShopSnapshot;
}

export interface BagChangedEvent {
  type: typeof GameEventType.BAG_CHANGED;
  bag: BagSnapshot;
}

export interface RocketChangedEvent {
  type: typeof GameEventType.ROCKET_CHANGED;
  rocket: RocketSnapshot;
}

export interface RocketTickEvent {
  type: typeof GameEventType.ROCKET_TICK;
  realtime: RocketRealtimeSnapshot;
}

export interface RocketCasinoChangedEvent {
  type: typeof GameEventType.ROCKET_CASINO_CHANGED;
  casinoModal: RocketCasinoModalSnapshot;
}

export interface RocketContractChangedEvent {
  type: typeof GameEventType.ROCKET_CONTRACT_CHANGED;
  contractModal: RocketContractModalSnapshot | null;
}

export interface TowerChangedEvent {
  type: typeof GameEventType.TOWER_CHANGED;
  tower: import('./snapshots.js').TowerSnapshot;
}

export interface ExpeditionChangedEvent {
  type: typeof GameEventType.EXPEDITION_CHANGED;
  expedition: import('./snapshots.js').ExpeditionSnapshot;
}

export interface ArenaChangedEvent {
  type: typeof GameEventType.ARENA_CHANGED;
  arena: import('./snapshots.js').ArenaSnapshot;
}

export interface PokedexChangedEvent {
  type: typeof GameEventType.POKEDEX_CHANGED;
  pokedex: import('./snapshots.js').PokedexSnapshot;
}

export interface ShinyFoundEvent {
  type: typeof GameEventType.SHINY_FOUND;
  creatureName: string;
}

export interface LegendaryFoundEvent {
  type: typeof GameEventType.LEGENDARY_FOUND;
  creatureName: string;
}

export interface TowerStartedEvent {
  type: typeof GameEventType.TOWER_STARTED;
}

export interface TowerCompletedEvent {
  type: typeof GameEventType.TOWER_COMPLETED;
  floor: number;
}

export interface ArenaStartedEvent {
  type: typeof GameEventType.ARENA_STARTED;
  arenaId: string;
}

export interface ArenaCompletedEvent {
  type: typeof GameEventType.ARENA_COMPLETED;
  arenaId: string;
}

export interface DpsMeterUpdatedEvent {
  type: typeof GameEventType.DPS_METER_UPDATED;
}

export interface FarmingMetricsUpdatedEvent {
  type: typeof GameEventType.FARMING_METRICS_UPDATED;
}

export interface MartAutoPurchaseUpdatedEvent {
  type: typeof GameEventType.MART_AUTO_PURCHASE_UPDATED;
}

export interface AfkSummaryChangedEvent {
  type: typeof GameEventType.AFK_SUMMARY_CHANGED;
}

export interface MiltankFarmChangedEvent {
  type: typeof GameEventType.MILTANK_FARM_CHANGED;
  miltankFarm: import('./snapshots.js').MiltankFarmSnapshot;
}

export interface FeticheChangedEvent {
  type: typeof GameEventType.FETICHE_CHANGED;
  fetiche: import('../lib/feticheSnapshot.js').FeticheSnapshot;
}

export interface ZRingChangedEvent {
  type: typeof GameEventType.Z_RING_CHANGED;
  unlockedCount: number;
  activeCrystalId: string | null;
}

export interface PokePelagoChangedEvent {
  type: typeof GameEventType.POKE_PELAGO_CHANGED;
  pokePelago: import('./snapshots.js').PokePelagoSnapshot;
}

// ─── Union ───

export type GameEvent =
  | StateUpdatedEvent
  | ResourcesChangedEvent
  | TeamChangedEvent
  | TeamHeaderStatsChangedEvent
  | StatsChangedEvent
  | StorageChangedEvent
  | StorageSortChangedEvent
  | PensionChangedEvent
  | ZoneChangedEvent
  | RegionChangedEvent
  | CombatStartedEvent
  | CombatEndedEvent
  | CombatStateChangedEvent
  | CaptureStartedEvent
  | CaptureEndedEvent
  | ToastEvent
  | ModalOpenedEvent
  | ModalClosedEvent
  | LanguageChangedEvent
  | SettingsChangedEvent
  | EggHatchedEvent
  | EvolutionReadyEvent
  | SaveLoadedEvent
  | QuestAcceptedEvent
  | QuestCompletedEvent
  | QuestsChangedEvent
  | AchievementsChangedEvent
  | ShopChangedEvent
  | BagChangedEvent
  | RocketChangedEvent
  | RocketTickEvent
  | RocketCasinoChangedEvent
  | RocketContractChangedEvent
  | TowerChangedEvent
  | ExpeditionChangedEvent
  | ArenaChangedEvent
  | PokedexChangedEvent
  | ShinyFoundEvent
  | LegendaryFoundEvent
  | TowerStartedEvent
  | TowerCompletedEvent
  | ArenaStartedEvent
  | ArenaCompletedEvent
  | DpsMeterUpdatedEvent
  | FarmingMetricsUpdatedEvent
  | MartAutoPurchaseUpdatedEvent
  | AfkSummaryChangedEvent
  | MiltankFarmChangedEvent
  | FeticheChangedEvent
  | ZRingChangedEvent
  | PokePelagoChangedEvent;
